-- Seed Class 6 AI Literacy curriculum (Part 2 PDF) under subjects.slug = 'ai'.
-- Idempotent. Run after 012_ai_program_subject.sql.
-- Source: docs/AICUMEN_Class6_AI_Curriculum 2.pdf

BEGIN;

INSERT INTO content_ingest_batches (source_label, source_file, source_kind, row_count, notes)
VALUES (
  'class6_ai_curriculum_v1',
  'docs/AICUMEN_Class6_AI_Curriculum 2.pdf',
  'manual',
  17,
  'Generated by scripts/generate_grade6_ai_seed.ts — full PROBLEM / Socratic ladder / EXTEND from PDF'
)
ON CONFLICT (source_label) DO UPDATE SET
  row_count = EXCLUDED.row_count,
  ingested_at = NOW();

DO $$
DECLARE
  subj_id INTEGER;
  ch_id INTEGER;
  act_id INTEGER;
  stem_id INTEGER;
BEGIN
  SELECT id INTO subj_id FROM subjects WHERE slug = 'ai';
  IF subj_id IS NULL THEN
    RAISE EXCEPTION 'AI subject not found — run migration 012_ai_program_subject.sql first';
  END IF;

  -- Module 1: What Is AI?
  SELECT c.id INTO ch_id
    FROM chapters c
   WHERE c.subject_id = subj_id AND c.chapter_code = '1';
  IF ch_id IS NULL THEN
    INSERT INTO chapters (subject_id, grade, chapter_code, title, anchor_curriculum, metadata)
    VALUES (
      subj_id, 6, '1', 'What Is AI?',
      'CBSE Class 6 AI Literacy',
      '{"hours":5,"curriculum_pack":"grade6_ai_literacy","blurb":"Machine intelligence vs. human intelligence, AI vs. automation, and the three ways machines learn."}'::jsonb
    ) RETURNING id INTO ch_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m1-ai-or-just-a-machine') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m1-ai-or-just-a-machine', 'AI or Just a Machine?', 'quest', 'Class 6 AI',
      1, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M1-01","theme":"Everyday Tech","difficulty":"Developing","stars":1,"emoji":"🤖","accent":"teal","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M1-01', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'Four gadgets are named: a kitchen weighing scale, a UPI app that flags a suspicious payment, a ceiling fan regulator, and a phone camera that recognises faces to unlock. Which of these are AI, and which are simple automation?', NULL,
      '{"answer_type":"short_text","body":{"value":"Automation: the kitchen scale and fan regulator, both follow one fixed rule with no learning involved. AI: the UPI fraud flag and face-unlock camera, both learned a pattern from many past examples."}}'::jsonb,
      '{"run_it":"Hold up (or draw) four cards, one per gadget. Students physically move to an \"AI\" corner or an \"Automation\" corner of the room for each one, then defend their choice.","grade":6}'::jsonb,
      'RUN IT: Hold up (or draw) four cards, one per gadget. Students physically move to an "AI" corner or an "Automation" corner of the room for each one, then defend their choice.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'For each gadget, ask: does it follow one instruction someone wrote in advance, or does it seem to have looked at many examples first?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'Look at the kitchen scale and the fan regulator together. What do the two of them have in common in how they work?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'Now look at the UPI fraud flag and the face-unlock camera. What would each of them have needed to see many times before, in order to work at all?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'Ask: could the fan regulator ever become AI? What would have to change? (It would need to learn a pattern, for instance adjusting itself based on how hot the room usually gets at that time of day.)',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m1-sorting-mangoes') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m1-sorting-mangoes', 'Sorting Mangoes with Meera Aunty', 'quest', 'Class 6 AI',
      2, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M1-02","theme":"Kirana / Market","difficulty":"Developing","stars":2,"emoji":"🥭","accent":"amber","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M1-02', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'Meera Aunty has sorted 40 mangoes into "ripe" and "raw" piles, and every mango already has a little sticker saying which pile it belongs to. Her nephew watches all 40, then picks up mango number 41, which has no sticker, and predicts which pile it belongs to. What kind of learning is this?', NULL,
      '{"answer_type":"short_text","body":{"value":"This is supervised learning: the nephew learns from mangoes that already carry the correct label, then applies that pattern to a new, unlabelled case."}}'::jsonb,
      '{"run_it":"Bring (or draw) 10 mango cards, 5 labelled \"ripe\" and 5 labelled \"raw,\" with colour and firmness noted on each. Add one unlabelled card and have students predict its label using the pattern from the first 10.","grade":6}'::jsonb,
      'RUN IT: Bring (or draw) 10 mango cards, 5 labelled "ripe" and 5 labelled "raw," with colour and firmness noted on each. Add one unlabelled card and have students predict its label using the pattern from the first 10.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'What''s the difference between having a labelled example and not having one?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'Did the first 40 mangoes already have their correct answer, ripe or raw, written on them?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'So is the nephew guessing mango 41''s label from nothing at all, or from the pattern in 40 labelled examples?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'What would happen if half the stickers were wrong? Would the nephew still learn the right pattern? (This is a gentle first brush with the idea of noisy or incorrect training data.)',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m1-unlabelled-spice-box') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m1-unlabelled-spice-box', 'The Unlabelled Spice Box', 'quest', 'Class 6 AI',
      3, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M1-03","theme":"Kirana / Market","difficulty":"Developing","stars":2,"emoji":"🌶️","accent":"amber","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M1-03', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'A new shop assistant is handed a box with 30 loose spice packets, no labels, all mixed together. He is told to "group the similar ones together" without being told what the groups should be called. He ends up with piles by smell and colour: reddish-orange powders in one pile, dark whole pods in another, pale seeds in a third. What kind of learning does this match?', NULL,
      '{"answer_type":"short_text","body":{"value":"This is unsupervised learning: there are no labels at all, the assistant (or system) finds its own structure by comparing similarities."}}'::jsonb,
      '{"run_it":"Give students a mixed set of 12–15 small objects (buttons, beads, pulses) with no labels and ask them to form their own groups, then explain the rule they used.","grade":6}'::jsonb,
      'RUN IT: Give students a mixed set of 12–15 small objects (buttons, beads, pulses) with no labels and ask them to form their own groups, then explain the rule they used.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'Were the spice packets given any names or labels to begin with?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'So how did the assistant decide which pile a packet belonged to, if nobody told him?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'If there''s no correct answer given in advance, and the groups are discovered rather than told, what kind of learning does that sound like?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'Two students given the identical unlabelled box may form different groupings. Discuss: is one of them wrong, or can both groupings be valid?',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m1-learning-to-fly-a-kite') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m1-learning-to-fly-a-kite', 'Learning to Fly a Kite', 'quest', 'Class 6 AI',
      4, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M1-04","theme":"Everyday Life","difficulty":"Secure","stars":3,"emoji":"🪁","accent":"sky","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M1-04', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'Aryan has never flown a kite before. Nobody gives him a rulebook. He tries pulling the string a little, the kite dips, he tries pulling harder, it climbs, he keeps adjusting based on what happens each time, and after twenty tries, he can keep the kite steady. Which of the three learning types does this match, and why?', NULL,
      '{"answer_type":"short_text","body":{"value":"This is reinforcement learning: there''s no example data at all, only trial, a consequence (the kite rising or falling), and adjustment toward a goal."}}'::jsonb,
      '{"run_it":"Have a small group play a simple hand-clap rhythm game where a \"reward\" (a point, a clap-back) is given only for a correct pattern, so the group has to adjust their rhythm attempt by attempt.","grade":6}'::jsonb,
      'RUN IT: Have a small group play a simple hand-clap rhythm game where a "reward" (a point, a clap-back) is given only for a correct pattern, so the group has to adjust their rhythm attempt by attempt.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'Did anyone hand Aryan a rulebook or a set of correct examples before he started flying the kite?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'What happens right after each pull of the string, does something tell him whether that pull was right or wrong?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'Is that "something" a labelled example, or more like a consequence, the kite rising or dipping, that he adjusts to?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'What is playing the role of the "reward" in Aryan''s kite example? What would happen if the reward (the kite staying up) never came, no matter what he tried?',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m1-name-that-learning-type') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m1-name-that-learning-type', 'Name That Learning Type', 'quest', 'Class 6 AI',
      5, 20, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M1-05","theme":"Mixed Review","difficulty":"Secure","stars":3,"emoji":"🎯","accent":"teal","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M1-05', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'Four short scenarios are read aloud: (a) a music app groups songs into "playlists you might like" with no one telling it what the playlists should be, (b) a doctor''s assistant predicts a disease from thousands of past patient records that were each marked with the correct diagnosis, (c) a robot vacuum learns the fastest route around a room only after bumping into furniture many times, (d) an app sorts old family photos into folders by comparing them to a set of pictures you already tagged with names. For each, name the learning type.', NULL,
      '{"answer_type":"short_text","body":{"value":"(a) Unsupervised, groups songs with no given labels. (b) Supervised, learns from records already labelled with the correct diagnosis. (c) Reinforcement, learns by trial, error, and consequence. (d) Supervised, learns from photos you already labelled with names."}}'::jsonb,
      '{"run_it":"Read one scenario at a time. Students hold up one of three cards (Supervised / Unsupervised / Reinforcement) simultaneously, so answers cannot be copied from a neighbour.","grade":6}'::jsonb,
      'RUN IT: Read one scenario at a time. Students hold up one of three cards (Supervised / Unsupervised / Reinforcement) simultaneously, so answers cannot be copied from a neighbour.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'For each scenario, ask first: is there labelled example data given upfront, no labels at all, or just trial-and-error feedback?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'If there are no labels and no reward, but the system is grouping things by similarity, what does that sound like?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'If there IS a reward or consequence driving the behaviour, but no upfront correct-answer examples, what does that sound like instead?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'Ask students to invent one new scenario of their own, from home or their school, for each of the three learning types.',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  -- Module 2: Basic Data Concepts
  SELECT c.id INTO ch_id
    FROM chapters c
   WHERE c.subject_id = subj_id AND c.chapter_code = '2';
  IF ch_id IS NULL THEN
    INSERT INTO chapters (subject_id, grade, chapter_code, title, anchor_curriculum, metadata)
    VALUES (
      subj_id, 6, '2', 'Basic Data Concepts',
      'CBSE Class 6 AI Literacy',
      '{"hours":5,"curriculum_pack":"grade6_ai_literacy","blurb":"Recognising data types, and organising raw information into something a machine, or a mentor, can actually read."}'::jsonb
    ) RETURNING id INTO ch_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m2-what-kind-of-data') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m2-what-kind-of-data', 'What Kind of Data Is This?', 'quest', 'Class 6 AI',
      1, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M2-01","theme":"School Life","difficulty":"Developing","stars":1,"emoji":"📊","accent":"sky","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M2-01', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'Four items are shown: the class attendance register, a voice note from the school announcement speaker, a photo of the school Republic Day parade, and a wedding invitation card. Sort each into one of four data types: text, number, image, or sound.', NULL,
      '{"answer_type":"short_text","body":{"value":"Attendance register: mainly numbers (with some text). Announcement voice note: sound. Republic Day photo: image. Wedding card: text."}}'::jsonb,
      '{"run_it":"Bring four real or printed examples into class and have students physically sort them under four labelled headings on a table.","grade":6}'::jsonb,
      'RUN IT: Bring four real or printed examples into class and have students physically sort them under four labelled headings on a table.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'Does this item contain written words, numbers, a picture you can see, or something you can only hear?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'Look closely at the attendance register, could it actually hold more than one data type at once?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'Sound is different from image, and text is different from number, which of the four fits each remaining item best?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'Can one item hold more than one data type at once? (The attendance register has both text, names, and numbers, roll numbers and present/absent counts.)',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m2-organise-kirana-shelf') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m2-organise-kirana-shelf', 'Organise the Kirana Shelf', 'quest', 'Class 6 AI',
      2, 20, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M2-02","theme":"Kirana / Market","difficulty":"Developing","stars":2,"emoji":"🛒","accent":"amber","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M2-02', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'A shopkeeper has a messy list of 20 items scribbled on paper: rice, soap, toothpaste, dal, shampoo, wheat flour, and so on, with prices written next to each in no particular order. Organise this into a clean table with clear categories (for example, Groceries, Personal Care) and columns for item name and price.', NULL,
      '{"answer_type":"short_text","body":{"value":"A worked example table: categories Groceries and Personal Care, with item name and price columns, alphabetised within each category. Sample: Groceries — Dal (1 kg) 110, Rice (1 kg) 65, Wheat flour (1 kg) 48; Personal Care — Shampoo (small) 90, Soap 35, Toothpaste 55. (Prices simulated for teaching.)"}}'::jsonb,
      '{"run_it":"Give groups the scrambled list on paper strips. They physically arrange the strips into a table on the floor or a large sheet before copying it into a notebook.","grade":6}'::jsonb,
      'RUN IT: Give groups the scrambled list on paper strips. They physically arrange the strips into a table on the floor or a large sheet before copying it into a notebook.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'Before organising anything, can you sort the 20 items into just two or three big groups?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'Within a group like "Personal Care," is there an order that would make the list easier to scan, like alphabetical?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'What information does each item need next to it to actually be useful, just a name, or a name and a price?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'Once organised, ask: which category has the most items? Which is more expensive on average? Notice how organising data makes new questions answerable that were invisible in the messy list.',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m2-reading-monsoon-chart') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m2-reading-monsoon-chart', 'Reading the Monsoon Chart', 'quest', 'Class 6 AI',
      3, 15, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M2-03","theme":"Weather / Geography","difficulty":"Secure","stars":3,"emoji":"🌧️","accent":"sky","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M2-03', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

    INSERT INTO questions (activity_id, role, sort_order, stem, hint, answer_spec, context, teacher_notes)
    VALUES (
      act_id, 'stem', 0, 'A simple bar chart shows rainfall (in mm, simulated figures) for June through September in a small town: June 180, July 310, August 260, September 140. Which month had the heaviest rainfall? How much more rain fell in July than September?', NULL,
      '{"answer_type":"short_text","body":{"value":"Heaviest rainfall: July (310 mm). Difference between July and September: 310 − 140 = 170 mm. (Rainfall figures here are simulated for the exercise, not real recorded data for any specific town.)"}}'::jsonb,
      '{"run_it":"Draw the four bars on the board without numbers first. Have students estimate values purely by comparing bar heights before revealing the numbers.","grade":6}'::jsonb,
      'RUN IT: Draw the four bars on the board without numbers first. Have students estimate values purely by comparing bar heights before revealing the numbers.'
    ) RETURNING id INTO stem_id;

    INSERT INTO questions (activity_id, role, sort_order, label, stem, teacher_notes)
    VALUES
      (act_id, 'coach_step', 1, 'Clue 1', 'Which bar on the chart reaches the highest point?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 2, 'Clue 2', 'Now find July''s bar and September''s bar specifically, which one is taller, and by roughly how much?', 'Reveal one clue per student attempt.'),
      (act_id, 'coach_step', 3, 'Clue 3', 'To find "how much more" rain fell in one month than another, what do you do with the two numbers, add them or subtract them?', 'Reveal one clue per student attempt.');

    INSERT INTO questions (activity_id, parent_question_id, role, sort_order, stem, answer_spec)
    VALUES (
      act_id, stem_id, 'extend', 4, 'If a farmer had to pick the single best month to plant a crop that dislikes too much water but needs some rain, which month from this chart looks safest, and why?',
      '{"answer_type":"open_rubric","body":{"rubric":["Reasoned discussion; answers may vary."]}}'::jsonb
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM activities WHERE slug = 'ai6-m2-build-your-own-data-table') THEN
    INSERT INTO activities (
      chapter_id, slug, title, activity_type, source_type_label,
      sort_order, estimated_minutes, ct_skills, ai_concept, status, metadata,
      external_id, chapter_dependent, enrichment_status
    ) VALUES (
      ch_id, 'ai6-m2-build-your-own-data-table', 'Build Your Own Data Table', 'quest', 'Class 6 AI',
      4, 20, ARRAY['ai_literacy']::text[], NULL, 'published',
      '{"quest_code":"AI6-M2-04","theme":"Classroom Activity","difficulty":"Developing","stars":2,"emoji":"📋","accent":"teal","source":"AICUMEN_Class6_AI_Curriculum"}'::jsonb,
      'AI6-M2-04', TRUE, 'enriched'
    ) RETURNING id INTO act_id;

