      '{"answer_type":"short_text","body":{"value":"The sequence repeats in a fixed 3-step cycle: A, C, B. After ...A, C, B, A, C, the next is B."}}'::jsonb,
      '{"run_it":"Use physical building cards (or students standing in a line) and have the class physically continue the sequence by stepping into the next position.","grade":6}'::jsonb,
